/**
 * Friday Attendance Reconciliation — "Missing Today" (M3, demo/mock only)
 *
 * After the Friday check-in window closes at 13:00, leadership needs to
 * reconcile EXPECTED vs PRESENT vs MISSING:
 *
 *   Expected = 420 ┐
 *   Present  = 363 ├─ derived from the existing M2 source of truth
 *   Missing  =  57 ┘  (`getLiveOperations()`), never hard-coded here.
 *
 * This module is a DERIVED VIEW over the existing mock member/people data. It
 * does not introduce a second attendance dataset: the missing roster is built
 * deterministically from `members`, and remaining slots are generated by
 * recombining the same member name/ministry/group pools. Everything is pure —
 * no database, no API, no wall clock.
 *
 * Business rule: MISSING IS AN OBSERVABLE STATE, NOT A DIAGNOSIS. A missing
 * person is never labelled "at risk" or "disengaged"; the administrator decides
 * whether to review, assign follow-up, mark excused, or mark not expected.
 */

import { members, type Member } from "@/lib/mock-data/people";
import { followUps, type FollowUp } from "@/lib/mock-data/follow-ups";
import { getLiveOperations } from "@/lib/mock-data/live-operations";

// ─── Types ──────────────────────────────────────────────────────────────────

/** Local, admin-assigned triage state for a missing person (mock only). */
export type MissingTriageStatus = "missing" | "excused" | "not-expected" | "follow-up";

export type MissingStatusFilter = "all" | MissingTriageStatus;

export interface MissingPerson {
  id: string;
  /** Set when this person maps to an existing `members` record (Member 360). */
  memberId: string | null;
  name: string;
  avatar: string;
  ministry: string;
  group: string;
  lastAttendance: string;
  attendanceRate: number;
  consecutiveAbsences: number;
}

export interface ReconciliationSummary {
  present: number;
  expected: number;
  missing: number;
  attendanceRate: number;
  excused: number;
  notExpected: number;
  followUpNeeded: number;
}

export const MISSING_TRIAGE_STATUSES: readonly MissingTriageStatus[] = [
  "missing",
  "excused",
  "not-expected",
  "follow-up",
] as const;

// ─── Deterministic roster construction ──────────────────────────────────────

const PAST_ATTENDANCE_DATES = [
  "Aug 28, 2026",
  "Aug 21, 2026",
  "Aug 14, 2026",
  "Aug 7, 2026",
  "Jul 31, 2026",
  "Jul 24, 2026",
  "Jul 17, 2026",
  "Jul 10, 2026",
] as const;

function unique<T>(values: T[]): T[] {
  return Array.from(new Set(values));
}

function isRealValue(value: string | undefined): value is string {
  return Boolean(value) && value !== "—";
}

/** Small, stable PRNG so the generated portion of the roster never changes. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function consecutiveAbsencesFor(rate: number, fallbackSeed: number): number {
  const derived = Math.round((100 - rate) / 9);
  return Math.max(1, Math.min(8, derived > 0 ? derived : 1 + (fallbackSeed % 3)));
}

function memberToMissing(member: Member): MissingPerson {
  const rate = member.attendanceRate ?? 70;
  return {
    id: `missing-member-${member.id}`,
    memberId: member.id,
    name: `${member.firstName} ${member.lastName}`,
    avatar: member.avatar,
    ministry: isRealValue(member.ministry) ? member.ministry : "—",
    group: isRealValue(member.group) ? member.group : "—",
    lastAttendance: member.lastAttendance,
    attendanceRate: rate,
    consecutiveAbsences: consecutiveAbsencesFor(rate, Number(member.id)),
  };
}

/**
 * Builds the deterministic "Missing Today" roster. The size is always exactly
 * `getLiveOperations().missing` (57) so it reconciles with M1/M2.
 */
function buildMissingRoster(): MissingPerson[] {
  const { missing } = getLiveOperations();
  const roster: MissingPerson[] = [];
  const usedNames = new Set<string>();

  // 1) Real members first — these link to the existing Member 360 experience.
  for (const member of members) {
    if (roster.length >= missing) break;
    const person = memberToMissing(member);
    roster.push(person);
    usedNames.add(person.name);
  }

  // 2) Fill the remainder by recombining the SAME members' name/ministry/group
  //    pools (no second authored dataset).
  const firstNames = unique(members.map((m) => m.firstName));
  const lastNames = unique(members.map((m) => m.lastName));
  const ministries = unique(members.map((m) => m.ministry).filter(isRealValue));
  const groups = unique(members.map((m) => m.group).filter(isRealValue));

  const rand = mulberry32(20260918);
  let combo = 0;
  while (roster.length < missing) {
    const firstName = firstNames[combo % firstNames.length];
    const lastName = lastNames[Math.floor(combo / firstNames.length) % lastNames.length];
    combo++;
    const name = `${firstName} ${lastName}`;
    if (usedNames.has(name)) continue;
    usedNames.add(name);

    const index = roster.length;
    const rate = 42 + Math.floor(rand() * 54); // 42–95%
    roster.push({
      id: `missing-generated-${index + 1}`,
      memberId: null,
      name,
      avatar: `https://i.pravatar.cc/150?img=${((index * 7) % 70) + 1}`,
      ministry: ministries[index % ministries.length] ?? "—",
      group: groups[index % groups.length] ?? "—",
      lastAttendance: PAST_ATTENDANCE_DATES[index % PAST_ATTENDANCE_DATES.length],
      attendanceRate: rate,
      consecutiveAbsences: Math.max(1, Math.min(8, 1 + Math.floor(rand() * 7))),
    });
  }

  return roster;
}

let cachedRoster: MissingPerson[] | null = null;

export function getMissingToday(): MissingPerson[] {
  if (!cachedRoster) cachedRoster = buildMissingRoster();
  return cachedRoster;
}

export function getMissingPersonById(id: string): MissingPerson | undefined {
  return getMissingToday().find((person) => person.id === id);
}

// ─── Existing follow-up protection (no duplicates) ──────────────────────────

const OPEN_FOLLOW_UP_STATUSES: readonly FollowUp["status"][] = ["open", "in_progress", "pending", "in-progress", "overdue"];

function normalizeName(name: string): string {
  return name.trim().toLowerCase();
}

let openFollowUpsByName: Map<string, FollowUp> | null = null;

function getOpenFollowUpIndex(): Map<string, FollowUp> {
  if (!openFollowUpsByName) {
    openFollowUpsByName = new Map();
    for (const followUp of followUps) {
      if (!OPEN_FOLLOW_UP_STATUSES.includes(followUp.status)) continue;
      const key = normalizeName(followUp.person);
      if (!openFollowUpsByName.has(key)) openFollowUpsByName.set(key, followUp);
    }
  }
  return openFollowUpsByName;
}

/** Returns an existing OPEN follow-up for a person, if any (prevents duplicates). */
export function getOpenFollowUpForName(name: string): FollowUp | undefined {
  return getOpenFollowUpIndex().get(normalizeName(name));
}

// ─── Reconciliation summary ─────────────────────────────────────────────────

const EMPTY_STATUSES: Record<string, MissingTriageStatus> = {};

/**
 * Derives the reconciliation summary from the M2 source of truth plus the
 * local triage state. Rules:
 *   - Not Expected  → removed from the expected population AND from missing.
 *   - Excused       → still expected, but no longer unresolved missing.
 *   - Follow-up     → still missing; additionally counted as follow-up needed.
 *   - Present / Expected stay derived from `getLiveOperations()` when untouched.
 */
export function computeReconciliation(
  statuses: Record<string, MissingTriageStatus> = EMPTY_STATUSES
): ReconciliationSummary {
  const base = getLiveOperations();
  let excused = 0;
  let notExpected = 0;
  let followUpNeeded = 0;

  for (const person of getMissingToday()) {
    const status = statuses[person.id] ?? "missing";
    if (status === "excused") excused++;
    else if (status === "not-expected") notExpected++;
    else if (status === "follow-up") followUpNeeded++;
  }

  const expected = base.expectedAttendance - notExpected;
  const present = base.checkedIn;
  const missing = Math.max(0, expected - present - excused);
  const attendanceRate = expected > 0 ? Math.round((present / expected) * 1000) / 10 : 0;

  return { present, expected, missing, attendanceRate, excused, notExpected, followUpNeeded };
}

// ─── Filtering helpers ──────────────────────────────────────────────────────

export function getTriageStatus(
  statuses: Record<string, MissingTriageStatus>,
  personId: string
): MissingTriageStatus {
  return statuses[personId] ?? "missing";
}

/** "Missing" filter = unresolved (missing or follow-up-needed). */
export function matchesStatusFilter(status: MissingTriageStatus, filter: MissingStatusFilter): boolean {
  if (filter === "all") return true;
  if (filter === "missing") return status === "missing" || status === "follow-up";
  return status === filter;
}

export interface MissingFilterCriteria {
  status: MissingStatusFilter;
  ministry: string;
  group: string;
  search: string;
}

export function filterMissingPeople(
  roster: readonly MissingPerson[],
  statuses: Record<string, MissingTriageStatus>,
  criteria: MissingFilterCriteria
): MissingPerson[] {
  const query = criteria.search.trim().toLowerCase();
  return roster.filter((person) => {
    const status = getTriageStatus(statuses, person.id);
    if (!matchesStatusFilter(status, criteria.status)) return false;
    if (criteria.ministry !== "all" && person.ministry !== criteria.ministry) return false;
    if (criteria.group !== "all" && person.group !== criteria.group) return false;
    if (query && !person.name.toLowerCase().includes(query)) return false;
    return true;
  });
}

export function getMinistryOptions(roster: readonly MissingPerson[]): string[] {
  return unique(roster.map((person) => person.ministry).filter(isRealValue)).sort();
}

export function getGroupOptions(roster: readonly MissingPerson[]): string[] {
  return unique(roster.map((person) => person.group).filter(isRealValue)).sort();
}
